// Cart state and checkout totals for the Fieldwork Supply storefront.
const UNIT_PRICE_CENTS = 6400;
const SHIPPING_CENTS = 800;
const FREE_SHIPPING_THRESHOLD_CENTS = 10000;
let quantity = 0;

function calculateTotals(items) {
  const subtotal = items.reduce((sum, item) => sum + item.unitPriceCents * item.quantity, 0);
  const shipping =
    subtotal === 0 || subtotal >= FREE_SHIPPING_THRESHOLD_CENTS
      ? 0
      : SHIPPING_CENTS;
  return { subtotal, shipping, total: subtotal + shipping };
}

function money(cents) {
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
  }).format(cents / 100);
}

function setMoney(testId, cents) {
  const element = document.querySelector(`[data-testid="${testId}"]`);
  element.textContent = money(cents);
  element.dataset.cents = String(cents);
}

function render() {
  document.querySelector("#empty").hidden = quantity > 0;
  document.querySelector("#cart-item").hidden = quantity === 0;
  document.querySelector("#quantity").value = quantity || 1;
  document.querySelector('[data-testid="bag-count"]').textContent = quantity;
  document.querySelector('[data-testid="item-count"]').textContent =
    `${quantity} ${quantity === 1 ? "item" : "items"}`;
  document.querySelector("#decrease").disabled = quantity <= 1;
  document.querySelector("#increase").disabled = quantity >= 9;
  const items = quantity
    ? [{ unitPriceCents: UNIT_PRICE_CENTS, quantity }]
    : [];
  const totals = calculateTotals(items);
  setMoney("line-total", UNIT_PRICE_CENTS);
  setMoney("subtotal", totals.subtotal);
  setMoney("shipping", totals.shipping);
  setMoney("total", totals.total);
}

document.querySelector("#add-to-cart").addEventListener("click", () => {
  quantity = Math.min(9, quantity + 1);
  render();
});
document.querySelector("#increase").addEventListener("click", () => {
  quantity = Math.min(9, quantity + 1);
  render();
});
document.querySelector("#decrease").addEventListener("click", () => {
  quantity = Math.max(1, quantity - 1);
  render();
});
document.querySelector("#quantity").addEventListener("change", (event) => {
  const value = Number.parseInt(event.target.value, 10);
  quantity = Number.isFinite(value) ? Math.max(1, Math.min(9, value)) : 1;
  render();
});
render();

* {
  box-sizing: border-box;
}
body {
  margin: 0;
  font:
    14px/1.6 Arial,
    Helvetica,
    sans-serif;
  color: #293b32;
  background: #fcfbf7;
}
.announcement {
  background: #334a3d;
  color: #f4f4e9;
  text-align: center;
  padding: 10px;
  font-size: 11px;
  letter-spacing: 0.5px;
}
.announcement span {
  margin-left: 60px;
  opacity: 0.8;
}
header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 24px 6%;
  border-bottom: 1px solid #e3e3d9;
}
.wordmark {
  font-size: 22px;
  letter-spacing: 3px;
  font-weight: 800;
  color: inherit;
  text-decoration: none;
  line-height: 1.2;
}
.wordmark span {
  display: block;
  font-size: 8px;
  letter-spacing: 4px;
}
nav {
  font-size: 12px;
}
nav span {
  margin: 0 20px;
  color: #a5aa9f;
}
.bag {
  font-size: 12px;
}
.bag b {
  border-radius: 50%;
  background: #e5e9df;
  padding: 5px 9px;
  margin-left: 8px;
}
main {
  max-width: 1200px;
  margin: auto;
  padding: 30px 50px;
}
.crumb {
  font-size: 9px;
  letter-spacing: 1.8px;
  margin-bottom: 25px;
  color: #687566;
}
.layout {
  display: grid;
  grid-template-columns: 1.3fr 1fr;
  gap: 65px;
}
.product-art {
  height: 295px;
  background: #e7e9dd;
  position: relative;
  overflow: hidden;
  display: grid;
  place-items: center;
}
.edition {
  position: absolute;
  top: 17px;
  left: 20px;
  font-size: 8px;
  letter-spacing: 1.7px;
}
.art-caption {
  position: absolute;
  bottom: 15px;
  left: 20px;
  font-size: 8px;
  letter-spacing: 1.2px;
}
.pack {
  width: 155px;
  height: 195px;
  border-radius: 35px 35px 18px 18px;
  background: linear-gradient(100deg, #627154, #7e8968 45%, #59684d);
  box-shadow: 15px 20px 25px #2d392d30;
  position: relative;
  transform: rotate(-7deg);
}
.handle {
  position: absolute;
  width: 45px;
  height: 30px;
  border: 9px solid #45533f;
  top: -18px;
  left: 55px;
  border-radius: 12px;
}
.flap {
  position: absolute;
  top: 12px;
  left: -4px;
  width: 163px;
  height: 65px;
  border-radius: 30px 30px 20px 20px;
  background: linear-gradient(120deg, #859174, #677657);
  box-shadow: 0 4px 5px #283e2630;
}
.strap {
  position: absolute;
  top: 50px;
  width: 12px;
  height: 65px;
  background: #ae8e63;
  z-index: 2;
  border-radius: 2px;
  border-bottom: 9px solid #43513a;
}
.left {
  left: 28px;
}
.right {
  right: 28px;
}
.pocket {
  position: absolute;
  bottom: 15px;
  left: 22px;
  width: 111px;
  height: 60px;
  border: 1px solid #4a5a40;
  border-radius: 8px;
  background: #758362;
}
.pocket span {
  position: absolute;
  left: 39px;
  top: 22px;
  background: #d5c5a5;
  color: #4c503e;
  padding: 1px 6px;
  font-size: 8px;
}
.product-copy {
  display: flex;
  justify-content: space-between;
  margin-top: 20px;
}
.eyebrow {
  font-size: 8px;
  letter-spacing: 1.6px;
  color: #73806c;
}
h1 {
  font-family: Georgia, serif;
  font-size: 27px;
  font-weight: 400;
  line-height: 1.2;
  margin: 8px 0;
}
p {
  color: #778071;
  font-size: 11px;
}
.price {
  font-size: 19px;
  margin-top: 25px;
}
.primary {
  width: 100%;
  padding: 12px 16px;
  background: #334a3d;
  color: white;
  border: 0;
  font-size: 12px;
  display: flex;
  justify-content: space-between;
  cursor: pointer;
}
.details {
  display: flex;
  justify-content: space-between;
  margin-top: 12px;
  font-size: 9px;
  color: #74806e;
}
.cart {
  padding-top: 5px;
}
h2 {
  font:
    28px Georgia,
    serif;
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid #dedfd4;
  padding-bottom: 24px;
  margin: 6px 0 25px;
}
h2 span {
  font: 10px Arial;
  color: #76816e;
}
.item-row {
  display: flex;
  align-items: center;
  gap: 15px;
}
.mini-pack {
  width: 60px;
  height: 70px;
  background: #e6e9dc;
  display: grid;
  place-items: center;
  color: #6d7d57;
  font-size: 45px;
  line-height: 1;
}
.item-row h3 {
  font-size: 12px;
  margin: 0;
}
.item-row p {
  margin: 2px 0;
}
.item-row span {
  font-size: 10px;
}
.item-row strong {
  font-size: 12px;
  margin-left: auto;
}
.qty-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin: 18px 0 25px;
  font-size: 11px;
}
.stepper {
  display: flex;
  border: 1px solid #d7dccf;
}
.stepper button {
  border: 0;
  background: transparent;
  width: 30px;
  height: 28px;
  cursor: pointer;
}
.stepper input {
  border: 0;
  background: transparent;
  width: 30px;
  text-align: center;
  appearance: textfield;
  color: inherit;
  font-size: 11px;
}
.stepper input::-webkit-inner-spin-button {
  appearance: none;
}
.summary {
  border-top: 1px solid #d7dccf;
  padding-top: 20px;
}
.summary > div {
  display: flex;
  justify-content: space-between;
  font-size: 12px;
  margin-bottom: 12px;
}
.summary strong {
  font-weight: 500;
}
.summary p {
  font-size: 9px;
}
.summary .total {
  border-top: 1px solid #d7dccf;
  padding-top: 20px;
  margin-top: 20px;
  font-size: 15px;
}
.checkout {
  width: 100%;
  border: 0;
  padding: 15px;
  background: #e2e6da;
  color: #68765d;
  font-size: 10px;
  margin-top: 12px;
}
.secure {
  text-align: center;
  font-size: 8px;
}
#empty {
  color: #778071;
  padding: 30px 0 50px;
  font-size: 12px;
}
footer {
  border-top: 1px solid #e3e3d9;
  margin-top: 25px;
  padding: 20px 6%;
  display: flex;
  justify-content: space-between;
  font-size: 9px;
  color: #778071;
}
footer b {
  font-size: 9px;
  letter-spacing: 1.5px;
}
button:focus-visible,
a:focus-visible,
input:focus-visible {
  outline: 3px solid #b58d43;
  outline-offset: 3px;
}
[hidden] {
  display: none !important;
}
@media (max-width: 750px) {
  header {
    padding: 20px;
  }
  nav {
    display: none;
  }
  main {
    padding: 25px;
  }
  .layout {
    grid-template-columns: 1fr;
    gap: 35px;
  }
  .announcement span {
    display: none;
  }
  footer {
    gap: 20px;
    flex-wrap: wrap;
  }
}

