* {
  box-sizing: border-box;
}
body {
  margin: 0;
  font:
    14px/1.6 Arial,
    Helvetica,
    sans-serif;
  color: #293b32;
  background: #fcfbf7;
}
.announcement {
  background: #334a3d;
  color: #f4f4e9;
  text-align: center;
  padding: 10px;
  font-size: 11px;
  letter-spacing: 0.5px;
}
.announcement span {
  margin-left: 60px;
  opacity: 0.8;
}
header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 24px 6%;
  border-bottom: 1px solid #e3e3d9;
}
.wordmark {
  font-size: 22px;
  letter-spacing: 3px;
  font-weight: 800;
  color: inherit;
  text-decoration: none;
  line-height: 1.2;
}
.wordmark span {
  display: block;
  font-size: 8px;
  letter-spacing: 4px;
}
nav {
  font-size: 12px;
}
nav span {
  margin: 0 20px;
  color: #a5aa9f;
}
.bag {
  font-size: 12px;
}
.bag b {
  border-radius: 50%;
  background: #e5e9df;
  padding: 5px 9px;
  margin-left: 8px;
}
main {
  max-width: 1200px;
  margin: auto;
  padding: 30px 50px;
}
.crumb {
  font-size: 9px;
  letter-spacing: 1.8px;
  margin-bottom: 25px;
  color: #687566;
