This synthetic retail application has no payments, customer accounts or external dependencies.

## Source map

- `index.html` contains the product listing, bag controls and checkout summary.
- `cart.js` owns the in-memory bag state, price calculation, currency formatting and DOM updates.
- `styles.css` defines the responsive storefront and the CSS product illustration.

## Product behavior

The Canvas daypack costs 6,400 cents. Quantity controls accept integers from one through nine. Adding a product increases its quantity; a page reload clears the bag. Decreasing quantity stops at one.

Shipping is 800 cents for nonempty orders below 10,000 cents of merchandise. Orders at or above that merchandise threshold receive complimentary shipping. Empty bags have no shipping charge. Displayed amounts use US dollars and integer cents internally. No tax or coupon feature is implemented.

The bag's line amount, subtotal, shipping and order total are displayed independently. The quantity field and bag count reflect the number of units. Checkout is deliberately disabled because this is a synthetic application.

## Runtime

Serve the directory as static files at `/retail/`. The script is loaded with `defer`; DOM updates happen synchronously on click or quantity-change events. There is no API call, storage persistence, service worker or database in this target application.
"}, {"path": "fixtures/retail/cart.js", "origin_path": "fixtures/scenarios/empty-shipping/cart.js", "sha256": "4909f8cf145a82d4a83ff0ec8ea3dcf77b1d00d44321bac3b676efe5e6806e51", "content": "// Cart state and checkout totals for the Fieldwork Supply storefront.
const UNIT_PRICE_CENTS = 6400;
const SHIPPING_CENTS = 800;
const FREE_SHIPPING_THRESHOLD_CENTS = 10000;
let quantity = 0;

function calculateTotals(items) {
  const subtotal = items.reduce((sum, item) => sum + item.unitPriceCents * item.quantity, 0);
  const shipping =
    subtotal >= FREE_SHIPPING_THRESHOLD_CENTS
      ? 0
      : SHIPPING_CENTS;
  return { subtotal, shipping, total: subtotal + shipping };
}

function money(cents) {
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
  }).format(cents / 100);
}

function setMoney(testId, cents) {
  const element = document.querySelector(`[data-testid="${testId}"]`);
  element.textContent = money(cents);
  element.dataset.cents = String(cents);
}

function render() {
  document.querySelector("#empty").hidden = quantity > 0;
  document.querySelector("#cart-item").hidden = quantity === 0;
  document.querySelector("#quantity").value = quantity || 1;
  document.querySelector('[data-testid="bag-count"]').textContent = quantity;
  document.querySelector('[data-testid="item-count"]').textContent =
    `${quantity} ${quantity === 1 ? "item" : "items"}`;
  document.querySelector("#decrease").disabled = quantity <= 1;
  document.querySelector("#increase").disabled = quantity >= 9;
  const items = quantity
    ? [{ unitPriceCents: UNIT_PRICE_CENTS, quantity }]
    : [];
  const totals = calculateTotals(items);
  setMoney("line-total", quantity * UNIT_PRICE_CENTS);
  setMoney("subtotal", totals.subtotal);
  setMoney("shipping", totals.shipping);
  setMoney("total", totals.total);
}

document.querySelector("#add-to-cart").addEventListener("click", () => {
  quantity = Math.min(9, quantity + 1);
  render();
});
document.querySelector("#increase").addEventListener("click", () => {
  quantity = Math.min(9, quantity + 1);
  render();
});
document.querySelector("#decrease").addEventListener("click", () => {
  quantity = Math.max(1, quantity - 1);
  render();
});
document.querySelector("#quantity").addEventListener("change", (event) => {
  const value = Number.parseInt(event.target.value, 10);
  quantity = Number.isFinite(value) ? Math.max(1, Math.min(9, value)) : 1;
  render();
});
render();
