      : SHIPPING_CENTS;
  return { subtotal, shipping, total: subtotal + shipping };
}

function money(cents) {
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
  }).format(cents / 100);
}

