}
footer {
  border-top: 1px solid #e3e3d9;
  margin-top: 25px;
  padding: 20px 6%;
  display: flex;
  justify-content: space-between;
  font-size: 9px;
  color: #778071;
}
footer b {
  font-size: 9px;
  letter-spacing: 1.5px;
}
button:focus-visible,
a:focus-visible,
input:focus-visible {
  outline: 3px solid #b58d43;
  outline-offset: 3px;
}
[hidden] {
