* {
  box-sizing: border-box;
}
body {
  margin: 0;
  font:
    14px/1.6 Arial,
    Helvetica,
    sans-serif;
  color: #293b32;
  background: #fcfbf7;
}
.announcement {
  background: #334a3d;
  color: #f4f4e9;
  text-align: center;
  padding: 10px;
  font-size: 11px;
  letter-spacing: 0.5px;
}
.announcement span {
  margin-left: 60px;
  opacity: 0.8;
}
header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 24px 6%;
  border-bottom: 1px solid #e3e3d9;
}
.wordmark {
  font-size: 22px;
  letter-spacing: 3px;
  font-weight: 800;
  color: inherit;
  text-decoration: none;
  line-height: 1.2;
}
.wordmark span {
  display: block;
  font-size: 8px;
  letter-spacing: 4px;
}
nav {
  font-size: 12px;
}
nav span {
  margin: 0 20px;
  color: #a5aa9f;
}
.bag {
  font-size: 12px;
}
.bag b {
  border-radius: 50%;
  background: #e5e9df;
  padding: 5px 9px;
  margin-left: 8px;
}
main {
  max-width: 1200px;
  margin: auto;
  padding: 30px 50px;
}
.crumb {
  font-size: 9px;
  letter-spacing: 1.8px;
  margin-bottom: 25px;
  color: #687566;
}
.layout {
  display: grid;
  grid-template-columns: 1.3fr 1fr;
  gap: 65px;
}
.product-art {
  height: 295px;
  background: #e7e9dd;
  position: relative;
  overflow: hidden;
  display: grid;
  place-items: center;
}
.edition {
  position: absolute;
  top: 17px;
  left: 20px;
  font-size: 8px;
  letter-spacing: 1.7px;
}
.art-caption {
  position: absolute;
  bottom: 15px;
  left: 20px;
  font-size: 8px;
  letter-spacing: 1.2px;
}
.pack {
  width: 155px;
  height: 195px;
  border-radius: 35px 35px 18px 18px;
  background: linear-gradient(100deg, #627154, #7e8968 45%, #59684d);
  box-shadow: 15px 20px 25px #2d392d30;
  position: relative;
  transform: rotate(-7deg);
}
.handle {
  position: absolute;
  width: 45px;
  height: 30px;
  border: 9px solid #45533f;
  top: -18px;
  left: 55px;
  border-radius: 12px;
}
.flap {
  position: absolute;
  top: 12px;
  left: -4px;
  width: 163px;
  height: 65px;
  border-radius: 30px 30px 20px 20px;
  background: linear-gradient(120deg, #859174, #677657);
  box-shadow: 0 4px 5px #283e2630;
}
.strap {
  position: absolute;
  top: 50px;
  width: 12px;
  height: 65px;
  background: #ae8e63;
  z-index: 2;
  border-radius: 2px;
  border-bottom: 9px solid #43513a;
}
.left {
  left: 28px;
}
.right {
  right: 28px;
}
.pocket {
  position: absolute;
  bottom: 15px;
  left: 22px;
  width: 111px;
  height: 60px;
